"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["98365"],{16955(e,a,t){t.r(a),t.d(a,{metadata:()=>r,default:()=>u,frontMatter:()=>h,contentTitle:()=>c,toc:()=>d,assets:()=>p});var r=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-update-abhanumber","title":"Update ABHA number","description":"Replaces a placeholder (dummy) ABHA number with the beneficiary\'s real ABHA number in the ABHA_AUTH_TRANSACTION table.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-update-abhanumber.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-update-abhanumber","permalink":"/docs/main/docs/nhcx/v1/api/registry/endpoints/registry-update-abhanumber","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Update ABHA number","sidebar_label":"Update ABHA number","sidebar_class_name":"api-method api-method--post","description":"Replaces a placeholder (dummy) ABHA number with the beneficiary\'s real ABHA number in the ABHA_AUTH_TRANSACTION table.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Get beneficiary policies (V2)","permalink":"/docs/main/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-get-policies"},"next":{"title":"Link payer product","permalink":"/docs/main/docs/nhcx/v1/api/registry/endpoints/registry-product-link"}}'),n=t(62540),s=t(43023),i=t(75064),o=JSON.parse('{"id":"registry_update_abhanumber","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/update/abhanumber","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Update ABHA number","title":"Update ABHA number","description":"Replaces a placeholder (dummy) ABHA number with the beneficiary\'s real ABHA number in the ABHA_AUTH_TRANSACTION table.\\n\\n### Business purpose\\n\\nBeneficiaries are sometimes onboarded before their real ABHA is known, using a placeholder value. Because the member layer and the Patient resource both key on the ABHA number, a placeholder that is never corrected leaves the beneficiary undiscoverable and breaks the identifier rules for claim bundles. This endpoint, tagged Retrieving API and implemented by updateAbhaNumberController, lets the placeholder be swapped for the real number so that later policy lookups and claim transactions line up. The docs describe it as updating the ABHA number in the ABHA_AUTH_TRANSACTION table.\\n\\n### When to use\\n\\nUse it once the beneficiary\'s genuine ABHA number becomes available after an onboarding that used a dummy value, and before relying on ABHA-keyed policy lookups or building Patient identifiers for coverage-eligibility, preauth (workflow code 12) or claim bundles. The documentation does not restrict which participant role calls it, so treat it as a member-data correction step rather than part of any transaction workflow.\\n\\n### Preconditions\\n\\n- A valid Bearer token from the client-credentials call (POST /get/session, form-urlencoded client_ID, client_secret, grant_type=client_credentials); tokens last 1200 seconds, so refresh before expiry.\\n- HTTP headers Accept: application/json, Content-Type: application/json and bearer_auth: Bearer (the participant service uses bearer_auth, not Authorisation).\\n- Base path for the participant service: https://apisbx.ABDM.gov.in/pmjay/sbxhcx/participanthcxservice (sandbox) or https://apisprod.NHA.gov.in/pmjay/hcx/participanthcxservice (production).\\n- This is a synchronous plain-JSON registry call: no JWE envelope, no x-hcx-* protocol headers and no correlation ID are involved.\\n- Both the placeholder and the real ABHA must be known; the body is UpdateAbhaRequest with two optional strings, dummyAbha and realAbha.\\n- The gateway\'s error catalogue expects ABHA numbers in XX-XXXX-XXXX-XXXX form (NHCX-1018), while the member layer stores them without hyphens; the docs do not state which form this endpoint expects, so follow your instance\'s guidance.\\n\\n### Postconditions\\n\\nA successful call returns HTTP 200 with UpdateAbhaResponse, which carries optional successMessage and errorMessage strings. Unusually for this service, the 400, 404 and 500 responses also use UpdateAbhaResponse rather than the registry ErrorResponse envelope, so clients must read errorMessage rather than Error.code on failure. No callback follows. After the update, policy lookups and Patient identifiers should use the real ABHA; any provider-side policy cache built on the placeholder needs a forced refresh.\\n\\n### Common mistakes\\n\\n- Parsing failures as ErrorResponse; this endpoint returns UpdateAbhaResponse for 400, 404 and 500 as well as for success.\\n- Sending an empty body; both fields are optional in the schema, but the operation is meaningless without dummyAbha and realAbha.\\n- Inconsistent ABHA formatting between systems: NHCX-1018 requires XX-XXXX-XXXX-XXXX at the gateway, while x-hcx-ben-ABHA-ID and the member-layer lookups take the number without hyphens.\\n- Forgetting to refresh cached policies and stored Patient identifiers that still carry the placeholder.\\n- Omitting the Accept header or the Bearer prefix on bearer_auth.\\n\\n### Best practices\\n\\n- Record both the placeholder and the real ABHA with the TIMESTAMP of the change for audit purposes.\\n- Read successMessage and errorMessage on every response and treat a non-200 status as failure even if the body parses.\\n- Immediately re-run /participant/get/policies with forceRefresh: true for the affected beneficiary.\\n- Keep the ABHA formatting rule per field: hyphen-free for member lookups and x-hcx-ben-ABHA-ID, XX-XXXX-XXXX-XXXX where NHCX-1018 applies.\\n- Never log the token; log the ABHA change with the request identifier only.\\n\\n### Related scenario\\n\\nA state scheme enrols a beneficiary in a hurry with a dummy ABHA so that a policy can be linked and an emergency admission can proceed. After discharge the beneficiary completes ABHA creation and the real number is captured. The payer\'s system calls /update/abhanumber with dummyAbha and realAbha, receives a successMessage, and then calls /participant/get/policies with forceRefresh to make sure the real ABHA resolves the linked product. The hospital\'s billing team, preparing the final claim, refreshes its own policy cache so that the Claim bundle\'s Patient identifiers carry the PMJAY member ID and the real hyphen-free ABHA.\\n\\n### Specification\\n\\nChapter [Participants and policies](/docs/nhcx/v1/registries) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"dummyAbha","type":"string","required":false,"description":"","encrypted":false},{"name":"realAbha","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"dummyAbha":"99999999999999","realAbha":"12345678910111"},"responses":[{"status":"200","description":"A successful call returns HTTP 200 with UpdateAbhaResponse, which carries optional successMessage and errorMessage strings.","example":{"successMessage":"ABHA number updated successfully"}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"dummyAbha\\": \\"99999999999999\\",\\n  \\"realAbha\\": \\"12345678910111\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"dummyAbha\\": \\"99999999999999\\",\\n  \\"realAbha\\": \\"12345678910111\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"dummyAbha\\": \\"99999999999999\\",\\n        \\"realAbha\\": \\"12345678910111\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/update/abhanumber\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"dummyAbha\\": \\"99999999999999\\",\\n    \\"realAbha\\": \\"12345678910111\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let h={title:"Update ABHA number",sidebar_label:"Update ABHA number",sidebar_class_name:"api-method api-method--post",description:"Replaces a placeholder (dummy) ABHA number with the beneficiary's real ABHA number in the ABHA_AUTH_TRANSACTION table.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},c,p={},d=[];function l(e){return(0,n.jsx)(i.A,{operation:o})}function u(e={}){let{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}}}]);